package com.company.app.feature.settings.data.datasource

import kotlinx.serialization.Serializable

@Serializable
data class SettingsResponse(
    val pushEnabled: Boolean
)

package com.company.app.feature.settings.data.datasource

import io.ktor.client.HttpClient
import io.ktor.client.call.body
import io.ktor.client.request.get

class SettingsRemoteDataSource(
    private val httpClient: HttpClient
) {

    suspend fun fetchSettings(): SettingsResponse {
        return httpClient.get("/api/settings").body()
    }
}

package com.company.app.feature.settings.domain.repository

import com.company.app.feature.settings.domain.usecase.SettingsData

interface ISettingsRepository {
    suspend fun getSettings(): SettingsData
}

package com.company.app.feature.settings.data.repository

import com.company.app.feature.settings.data.datasource.SettingsRemoteDataSource
import com.company.app.feature.settings.domain.repository.ISettingsRepository
import com.company.app.feature.settings.domain.usecase.SettingsData

class SettingsRepository(
    private val remoteDataSource: SettingsRemoteDataSource
) : ISettingsRepository {

    override suspend fun getSettings(): SettingsData {
        val response = remoteDataSource.fetchSettings()
        return SettingsData(pushEnabled = response.pushEnabled)
    }
}

package com.company.app.feature.settings.domain.usecase

import com.company.app.common.domain.UseCase
import com.company.app.feature.settings.domain.repository.ISettingsRepository

class GetSettingsUseCase(
    private val repository: ISettingsRepository
) : UseCase<Unit, Result<SettingsData>> {

    override suspend fun execute(params: Unit): Result<SettingsData> {
        return try {
            Result.success(repository.getSettings())
        } catch (e: Exception) {
            Result.failure(e)
        }
    }
}
